class Solution:
    def bestRotation(self, A):
        N = len(A)
        change = [1] * N
        for i in range(N):
            change[(i-A[i]+1)%N] -= 1
        for i in range(1, N):
            change[i] += change[i-1]
        return change.index(max(change))

class Solution:
    def champagneTower(self, poured: int, r: int, c: int) -> float:
        quantity=defaultdict(int)
        quantity[(0,0)]=poured
        for i in range(r+1):
            flag=False
            for j in range(i+1):
                prev_flow=quantity[(i,j)]-1
                if prev_flow<=0:
                    continue
                flag=True
                quantity[(i,j)]=1
                quantity[(i+1,j)]+=prev_flow/2
                quantity[(i+1,j+1)]+=prev_flow/2
            if not flag: break
        return quantity[(r,c)]

